-- ==============================================
-- CRM Риэлтора — полная пересборка + импорт
-- Запускать ОДИН РАЗ в Supabase SQL Editor
-- ==============================================

-- Чистый старт
drop table if exists properties cascade;
drop table if exists clients cascade;
drop function if exists update_updated_at cascade;

-- Таблица клиентов
create table clients (
  id            uuid primary key default gen_random_uuid(),
  client_number int not null unique,
  name          text not null,
  phone         text,
  email         text,
  notes         text,
  request       text,
  budget        text,
  contact_date  date,
  status        text,
  priority      text,
  last_contact  date,
  next_contact  date,
  next_step     text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- Таблица объектов
create table properties (
  id                 uuid primary key default gen_random_uuid(),
  article            text not null unique,
  type               text not null check (type in ('apartment','house','land','commercial')),
  status             text not null default 'active' check (status in ('active','sold','reserved','withdrawn')),
  price              numeric(15,2) not null,
  area               numeric(10,2) not null,
  rooms              int,
  floor              int,
  total_floors       int,
  view               text,
  address            text not null,
  complex_name       text,
  description        text,
  photos             text[] not null default '{}',
  videos             text[] not null default '{}',
  owner_id           uuid references clients(id) on delete set null,
  area_sotki         numeric(10,2),
  communications     text[],
  cadastral_number   text,
  is_active_business boolean,
  has_wet_points     boolean,
  has_parking        boolean,
  entrance_groups    int,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

-- Индексы
create index idx_properties_type     on properties(type);
create index idx_properties_status   on properties(status);
create index idx_properties_owner_id on properties(owner_id);
create index idx_clients_number      on clients(client_number);
create index idx_clients_phone       on clients(phone);

-- Auto updated_at
create function update_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger trg_clients_updated_at
  before update on clients
  for each row execute function update_updated_at();

create trigger trg_properties_updated_at
  before update on properties
  for each row execute function update_updated_at();

-- RLS
alter table clients    enable row level security;
alter table properties enable row level security;

create policy allow_all_clients    on clients    for all using (true) with check (true);
create policy allow_all_properties on properties for all using (true) with check (true);

